@Composable
fun Register(patients: List<Patient>, onOpen: (Patient) -> Unit) {
  Scaffold(topBar = { TopAppBar(title = { Text("ANC Register") }) }) { pad ->
    LazyColumn(Modifier.padding(pad)) {
      items(patients) { p ->
        ListItem(
          modifier = Modifier.clickable { onOpen(p) },
          headlineContent = { Text(p.name) },
          supportingContent = { Text("Age ${p.age} · Due ${p.edd} · ${p.weeks} weeks") },
        )
        HorizontalDivider()
      }
    }
  }
}

